14:describe("conservativeDefaultAnswer: legal status", () => {
15:  const authorizationWordings = [
16:    "Are you authorized to work in the United States?",
17:    "Are you legally authorized to work in the United States without restriction?",
18:    "Do you have the right to work in the USA?",
19:    "Are you eligible to work in the US?",
20:    "United States work authorization?",
21:  ];
22:
23:  it.each(authorizationWordings)("answers %s with the negative", (q) => {
24:    const d = conservativeDefaultAnswer(q);
25:    expect(d).not.toBeNull();
26:    expect(d!.kind).toBe("boolean");
27:    // The polarity is the whole point: this must press "No", never "Yes".
28:    expect(resolveBooleanAnswer(d!.answer)).toBe("no");
29:  });
30:
31:  const sponsorshipWordings = [
32:    "Do you now or in the future require visa sponsorship?",
33:    "Will you require sponsorship for employment visa status?",
34:    "Do you need visa support to work for us?",
35:    "Do you require H-1B sponsorship?",
36:  ];
37:
38:  it.each(sponsorshipWordings)("answers %s as needing sponsorship", (q) => {
39:    const d = conservativeDefaultAnswer(q);
40:    expect(d).not.toBeNull();
41:    expect(d!.kind).toBe("boolean");
42:    // "I need sponsorship" is the claimless answer here — the polarity that
43:    // asserts nothing is the opposite of the authorization question's.
44:    expect(resolveBooleanAnswer(d!.answer)).toBe("yes");
45:  });
46:
47:  it("never produces a positive claim of authorization", () => {
48:    for (const q of [...authorizationWordings, ...sponsorshipWordings]) {
49:      const { answer } = conservativeDefaultAnswer(q)!;
50:      expect(answer).not.toMatch(/\bI am authorized\b|\bno sponsorship\b/i);
51:    }
52:  });
53:
54:  it("leaves a non-US right-to-work question alone", () => {
55:    // The candidate is authorized where they live; answering "no" to that would
56:    // be as false as answering "yes" to the US one.
57:    expect(
58:      conservativeDefaultAnswer("Are you authorized to work in Brazil?"),
59:    ).toBeNull();
60:  });
61:});
